head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF08303";
// 원본 : /etn/ULDSTF08303.gfm (ETN/ETF 투자유의종목 지정 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF08200 마감처리 > 투자유의 [지정] 단계)가 넘긴 업무처리번호가 없으면 신규, 있으면 상세를 조회해 수정 모드로 연다.
 *  - 신규는 [종목선택](ETN ULDSTF08045 / ETF ULDSTF08047)으로 종목을 여러 건 담아 한 번에 등록한다(서버 채번).
 *    부모가 종목을 넘겨 열었으면 그 종목 한 건만 두고 종목선택을 잠근다.
 *  - 수정·삭제는 그리드 행마다 차례로 보낸다. 조회기준일이 오늘보다 앞이면 모든 처리 버튼을 잠근다.
 *  - 삭제에 모두 성공하면 팝업을 닫고, 부모는 await 가 끝나면 목록을 다시 조회한다(원본 fn_parentRefresh 대체).
 *  - 공시안내문작성(ULDSTF92024)은 openPopup 의 data 로 넘기고 await 한다.
 *    92024 전환본이 아직 부모 getPar 를 부르므로 호환용 scwin.getPar 만 임시로 둔다(§10 #9).
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08303/ULDSTF08303.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)
scwin.isuCd = "";           // 부모 목록에서 고른 종목코드 (AS-IS arr[0] Isu_cd) — 신규인데 있으면 그 종목 한 건으로 시작
scwin.isuNm = "";           // 종목명 (AS-IS arr[1] Isu_nm)
scwin.secugrpId = "";       // 증권그룹ID EN: ETN, EF: ETF (AS-IS arr[2] Secugrp_id)
scwin.bzProcsNo = "";       // 업무처리번호 (AS-IS arr[4] fr_bz_procs_no) — 비면 신규. 행 클릭·저장 뒤 바뀐다
scwin.designDd = "";        // 지정일 기본값 (AS-IS arr[5] design_dd)
scwin.inqDd = "";           // 조회기준일 (AS-IS arr[6] Inq_dd) — 중복확인·저장 basDd, 오늘보다 앞이면 조회 전용
scwin.fstDtectDd = "";      // 최초적출일 (AS-IS arr[7] fst_dtect_dd) — 부모가 넘긴 종목의 최초지정일
scwin.isurCd = "";          // 발행기관코드 (AS-IS arr[8] Isur_cd)

// 화면 상태값
scwin.todayDd = "";         // 오늘 (yyyyMMdd) — AS-IS fn_todayDate (§5.6, §10 #6)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.selectedRow = -1;     // 그리드에서 고른 행 (AS-IS selectedGrdNum, 0 → -1) — 안내문작성 대상

// 고정값
scwin.DESIGN_CD = "03";                                 // ETP투자유의지정코드 03: 지정
scwin.SECUGRP_ID_EN = "EN";                             // ETN
scwin.SECUGRP_ID_EF = "EF";                             // ETF
scwin.DSCL_FORM_CD = { EN : "68391", EF : "99357" };    // 공시안내문 서식 — 상장지수증권 투자유의종목 지정 안내공시 / ETF 투자유의종목 지정
scwin.COMPLETE_YN_OK = "Y";                             // 등록·수정·삭제 응답 completeYn 의 성공 값 — TODO: 명세에 값이 없어 가정 (§10 #4)
scwin.DEFAULT_DESIGN_RSN = "지정예고일로부터 10매매거래일 이내에 장종료시 실시간 괴리율이\n"
    + "규정상 관리의무 비율의 2배 이상에 해당";
scwin.DEFAULT_INVSTWARN_CONTN = "지정일 포함 3매매거래일간(지정단위기간) 단일가매매가 시행됩니다.\n"
    + "투자유의종목 지정단위기간 중 장종료시 실시간 괴리율이 규정상 의무범위를 1일 이상 초과하는 경우\n"
    + "투자유의종목 지정이 연장될 수 있습니다. 또한, 지정단위기간 종료일의 장종료시 실시간 괴리율이 규정상\n"
    + "의무범위의 3배 이상인 경우 매매거래가 정지될 수 있습니다.";

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다. [종목선택]은 따로 다룬다(§4).
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 28
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 28
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 오늘 → 달력 바인딩 → 신규 준비 또는 상세 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.isuCd = String(param.isuCd ?? "");
    scwin.isuNm = String(param.isuNm ?? "");
    scwin.secugrpId = String(param.secugrpId ?? "");
    scwin.bzProcsNo = String(param.bzProcsNo ?? "");
    scwin.designDd = String(param.designDd ?? "");
    scwin.inqDd = String(param.inqDd ?? "");
    scwin.fstDtectDd = String(param.fstDtectDd ?? "");
    scwin.isurCd = String(param.isurCd ?? "");

    // 3) 오늘 — 원본 fn_todayDate 는 DB 조회(invstwarn_today_dd). 명세에 없어 서버 현재일로 둔다.
    // TODO: 영업일 기준 등 DB 값과 다를 수 있는지 확인 (§10 #6)
    scwin.todayDd = $c.date.getServerDateTime("yyyyMMdd");

    // 4) 달력 검사 바인딩(1회) — 단일 달력 (규칙 37)
    $c.date.checkCalendarFormat(edt_DesignDd, "yyyyMMdd");

    // 5) 신규·수정 분기 (원본 fn_onload)
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
        scwin.setIsuBtnState();
        $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
        return;
    }

    await scwin.selectDetail();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목선택 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_isu_oncellclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 지정종목 그리드 셀 클릭 — 고른 행을 안내문작성 대상으로 둔다. (원본 grid_1 OnClick)
 * @param {Number} row 행 index
 * @param {Number} col 열 index
 * @param {String} colId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_isu_oncellclick = async function (row, col, colId) {
    try {
        scwin.selectGridRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.grd_isu_oncellclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Dscl_onclick
 * @author Inswave
 * @date 2026. 10. 28
 * @description 안내문작성 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Dscl_onclick = async function (e) {
    try {
        await scwin.writeDscl();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08303.btn_Dscl_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 10. 28
 * @description 상세 조회. 업무처리번호로 지정 내역을 받아 입력 폼(dma_detail)에 두고, 그 종목을 그리드 한 행으로 둔 뒤
 * 조회기준일로 버튼 상태를 정한다. (원본 fn_onload 수정 분기 + dts_Mst OnLoadCompleted — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectDetail = async function () {
    const sbmOptions = {
        id : "sbm_selectDetail",
        method : "get",
        action : "/api/listing/lstproc/etn/invstwarn/select-one",
        target : "dma_detail=body",
        isProcessMsg : false
    };

    const requestData = {
        secugrpId : scwin.secugrpId,        // AS-IS SECUGRP_ID
        bzProcsNo : scwin.bzProcsNo         // AS-IS BZ_PROCS_NO (GUBUN_CD=03 은 명세에 없음 — §10 #3)
    };

    dma_detail.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 버튼을 잠근 채 둔다(init 1단계) — 신규 상태로 오인해 다시 등록하지 않게.
    if (!result.responseJSON?.success) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    // AS-IS CopyDataSet(dts_Mst, dts_Isu_Temp) — 조회한 종목을 그리드 한 행으로
    dlt_isu.setJSON([{
        isuCd : dma_detail.get("isuCd"),
        isuNm : dma_detail.get("isuNm"),
        bzProcsNo : dma_detail.get("bzProcsNo"),
        isurCd : dma_detail.get("isurCd"),
        comNm : "",                                 // TODO: 응답에 발행회사명 없음 — 안내문 mst COM_NM (§10 #8)
        addYn : dma_detail.get("addYn"),
        status : ""
    }]);
    scwin.selectedRow = -1;

    // AS-IS Isur_cd · fr_bz_procs_no = 첫 행 값
    scwin.isurCd = dma_detail.get("isurCd");
    scwin.bzProcsNo = dma_detail.get("bzProcsNo");

    scwin.setIsuBtnState();

    // 조회기준일이 오늘보다 앞이면 조회 전용 — 원본처럼 문자열 비교(조회기준일이 비어 있어도 잠긴다, §8 #9)
    $c.util.setButtonState("grpBtnBox", (scwin.inqDd < scwin.todayDd) ? "disabled" : "update", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.checkDuplicate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 종목마다 같은 기준일에 이미 지정돼 있는지 확인한다. 하나라도 중복이면 안내하고 true. (원본 fn_duplicate_check — §5.2)
 * @returns {Promise<Boolean>} 중복(또는 확인하지 못함)이면 true — 저장하지 않는다
 * @hidden N
 */
scwin.checkDuplicate = async function () {
    const rowCount = dlt_isu.getRowCount();

    for (let i = 0; i < rowCount; i++) {
        const sbmOptions = {
            id : "sbm_checkDuplicate",
            method : "get",
            action : "/api/listing/lstproc/etn/invstwarn/select-check-duplicate",
            isProcessMsg : false
        };

        const requestData = {
            etpInvstwarnDesignCd : scwin.DESIGN_CD,             // AS-IS ETP_INVSTWARN_DESIGN_CD
            basDd : scwin.inqDd,                                // AS-IS BAS_DD = Inq_dd
            isuCd : dlt_isu.getCellData(i, "isuCd")             // AS-IS ISU_CD
        };

        const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
        if (result?.skipped) return true;     // 진행 중 확인이 있어 이번 저장은 멈춘다

        if (!result.responseJSON?.success) {
            await $c.win.alert($c.stf.getMessageParam("MSG-A002", "중복확인"));
            return true;
        }

        // 명세: result.responseJSON.dupChk — TODO: 응답 봉투의 body 아래로 오는지 확인 (§10 #2)
        const dupChk = result.responseJSON.dupChk ?? result.responseJSON.body?.dupChk;
        if (dupChk === "Y") {
            await $c.win.alert("중복된 종목이 저장되어 있습니다.");
            return true;
        }
    }

    return false;
};

/**
 * @method
 * @name scwin.registerTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 등록. 그리드의 종목 전체를 한 번에 보내고(서버 채번), 응답의 업무처리번호 목록을 행마다 적는다.
 * (원본 fn_save 의 종목별 채번 + fn_save_trs(TRS_IDX_INSERT) 반복 — §5.3)
 * @returns {Promise<Boolean|null>} 성공 true, 실패 false, 중복 실행 건너뜀 null
 * @hidden N
 */
scwin.registerTrs = async function () {
    // 전문 머리 — 입력 폼(dma_detail) + 화면 고정값
    dma_register.setEmptyValue();
    dma_register.setJSON({
        secugrpId : scwin.secugrpId,
        etpInvstwarnDesignCd : scwin.DESIGN_CD,
        designDd : dma_detail.get("designDd"),
        designRsn : dma_detail.get("designRsn"),
        etpInvstwarnContn : dma_detail.get("etpInvstwarnContn"),
        misc : dma_detail.get("misc"),
        basDd : scwin.inqDd,
        // 신규 그리드의 addYn 은 전 행이 같다(부모 종목 1행 빈 값 / 종목선택 결과 전 행 Y — AS-IS 보장, §5.3) → 첫 행 기준
        fstDesignDd : scwin.getFstDesignDd(dlt_isu.getCellData(0, "addYn"))
    });

    // 전문 목록 — 업무처리번호는 비워 서버가 채번한다(setJSON 이 정의된 열만 남긴다)
    dlt_register.setJSON(dlt_isu.getAllJSON().map(row => ({
        bzProcsNo : "",
        isuCd : row.isuCd,
        isurCd : row.isurCd,
        addYn : row.addYn
    })));

    const sbmOptions = {
        id : "sbm_registerTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/invstwarn/register",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const requestData = {
        ...dma_register.getJSON(),
        isuList : dlt_register.getAllJSON()     // AS-IS dts_Isu_Temp
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!scwin.isSaveSuccess(result)) return false;

    // 응답 업무처리번호 목록(요청 isuList 순서)을 행에 적는다 — 원본 OnSuccess 의 BZ_PROCS_NO 기록
    // TODO: bzProcsNoList 가 배열인지 쉼표 문자열인지 확인 (§10 #4) — 원값은 body 에서 직접 읽는다
    const noList = scwin.toNoList(result.responseJSON?.body?.bzProcsNoList);
    dlt_isu.setBroadcast(false);
    for (let i = 0; i < dlt_isu.getRowCount(); i++) {
        dlt_isu.setCellData(i, "bzProcsNo", noList[i] ?? "");
        dlt_isu.setCellData(i, "status", "Y");
    }
    dlt_isu.setBroadcast(true, true);
    return true;
};

/**
 * @method
 * @name scwin.modifyTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행을 수정한다. 결과를 그 행의 status 에 남긴다. (원본 fn_update 반복 안의 fn_copy_dts + fn_save_trs(TRS_IDX_UPDATE) — §5.4)
 * @param {Number} row 그리드 행 index
 * @returns {Promise<Boolean|null>} 성공 true, 실패 false, 중복 실행 건너뜀 null
 * @hidden N
 */
scwin.modifyTrs = async function (row) {
    const addYn = dlt_isu.getCellData(row, "addYn");

    dma_update.setEmptyValue();
    dma_update.setJSON({
        bzProcsNo : dlt_isu.getCellData(row, "bzProcsNo"),
        secugrpId : scwin.secugrpId,
        isuCd : dlt_isu.getCellData(row, "isuCd"),
        isurCd : dlt_isu.getCellData(row, "isurCd"),
        designDd : dma_detail.get("designDd"),
        designRsn : dma_detail.get("designRsn"),
        etpInvstwarnContn : dma_detail.get("etpInvstwarnContn"),
        misc : dma_detail.get("misc"),
        addYn : addYn,
        basDd : scwin.inqDd,
        etpInvstwarnDesignCd : scwin.DESIGN_CD,
        fstDesignDd : scwin.getFstDesignDd(addYn)
    });

    const sbmOptions = {
        id : "sbm_modifyTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/invstwarn/modify",
        ref : "dma_update",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    const isSuccess = scwin.isSaveSuccess(result);
    dlt_isu.setCellData(row, "status", isSuccess ? "Y" : "N");
    return isSuccess;
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 한 행을 삭제한다. 결과를 그 행의 status 에 남긴다. (원본 fn_delete 반복 안의 fn_save_trs(TRS_IDX_DELETE) — §5.5)
 * @param {Number} row 그리드 행 index
 * @returns {Promise<Boolean|null>} 성공 true, 실패 false, 중복 실행 건너뜀 null
 * @hidden N
 */
scwin.removeTrs = async function (row) {
    dma_delete.setEmptyValue();
    dma_delete.setJSON({
        bzProcsNo : dlt_isu.getCellData(row, "bzProcsNo"),
        secugrpId : scwin.secugrpId,
        isuCd : dlt_isu.getCellData(row, "isuCd"),
        isurCd : dlt_isu.getCellData(row, "isurCd")
    });

    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/invstwarn/remove",
        ref : "dma_delete",
        target : "dma_resultSave=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    dma_resultSave.setEmptyValue();
    const result = await $c.sbm.executeDynamic(sbmOptions);
    if (result?.skipped) return null;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    const isSuccess = scwin.isSaveSuccess(result);
    dlt_isu.setCellData(row, "status", isSuccess ? "Y" : "N");
    return isSuccess;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 준비. 지정일은 부모가 넘긴 값, 지정사유·투자유의사항·기타는 표준 문구로 채우고,
 * 부모가 종목을 넘겼으면 그 종목을 그리드 한 행으로 둔다. 통신 없음.
 * (원본 fn_onload 신규 분기 + dts_Mst · dts_Isu_Temp OnLoadCompleted — §3, §6.1)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_detail.setEmptyValue();
    dlt_isu.removeAll();
    scwin.selectedRow = -1;

    if (!$c.util.isEmpty(scwin.isuCd)) {
        dlt_isu.setJSON([{
            isuCd : scwin.isuCd,
            isuNm : scwin.isuNm,
            bzProcsNo : "",
            isurCd : scwin.isurCd,
            comNm : "",
            addYn : "",         // 원본도 비움 — 저장 시 최초지정일은 부모의 최초적출일(§6.6)
            status : ""
        }]);
    }

    dma_detail.set("designDd", scwin.designDd);
    dma_detail.set("designRsn", scwin.DEFAULT_DESIGN_RSN);
    dma_detail.set("etpInvstwarnContn", scwin.DEFAULT_INVSTWARN_CONTN);
    dma_detail.set("misc", "-");
};

/**
 * @method
 * @name scwin.setIsuBtnState
 * @author Inswave
 * @date 2026. 10. 28
 * @description [종목선택] 잠금 — 업무처리번호가 있거나(수정) 부모가 종목을 넘겼으면 잠근다. (원본 fn_SetIsuCdBtnShow — §6.2)
 * @returns
 * @hidden N
 */
scwin.setIsuBtnState = function () {
    img_SetIsuCd.setDisabled(!$c.util.isEmpty(scwin.bzProcsNo) || !$c.util.isEmpty(scwin.isuCd));
};

/**
 * @method
 * @name scwin.selectGridRow
 * @author Inswave
 * @date 2026. 10. 28
 * @description 그리드 행 선택 — 안내문작성 대상 행과 그 행의 발행기관코드·업무처리번호를 화면 상태값으로 둔다. (원본 fn_SelectGridRow — §6.3)
 * @param {Number} row 그리드 행 index
 * @returns
 * @hidden N
 */
scwin.selectGridRow = function (row) {
    if (row < 0 || row >= dlt_isu.getRowCount()) return;

    scwin.selectedRow = row;
    scwin.isurCd = dlt_isu.getCellData(row, "isurCd");
    scwin.bzProcsNo = dlt_isu.getCellData(row, "bzProcsNo");
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 28
 * @description 종목선택. 증권그룹에 맞는 종목선택 팝업(ETN ULDSTF08045 / ETF ULDSTF08047)을 열고, 돌려받은 종목 목록으로 그리드를 바꾼다.
 * 돌려받은 종목은 모두 이번에 새로 지정하는 종목(addYn Y)이다. (원본 img_SetIsuCd onclick + fn_GetParIsu/fn_SetParIsu — §6.4, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    // 원본은 EN·EF 외 증권그룹이면 아무것도 열지 않는다.
    const popupId = {
        [scwin.SECUGRP_ID_EN] : "ULDSTF08045",      // AS-IS fn_PopFindEtnCode()
        [scwin.SECUGRP_ID_EF] : "ULDSTF08047"       // AS-IS fn_PopFindEtfCode(Secugrp_id)
    }[scwin.secugrpId];
    if (!popupId) return;

    const data = {
        isurCd : "",                        // AS-IS arrPar[0]
        isuCd : "",
        gubun : "3",                        // AS-IS arrPar[1] — 3: 상장전체
        secugrpId : scwin.secugrpId,        // AS-IS fn_PopFindEtfCode(Secugrp_id)
        isuList : dlt_isu.getAllJSON()      // AS-IS CopyDataSet(dts_Isu_Temp, param_dts) — TODO: 팝업이 받는지 확인 (§10 #7)
    };
    const options = {
        id : popupId,
        popupName : "종목선택",
        width : 520,
        height : 440,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정 — 08045 는 sample-front 전환본(ui/stf/lst/common), 08047 은 전환본 없음 (§10 #7)
    const result = await $c.win.openPopup("/ui/lst/common/" + popupId + ".xml", options, data);

    // [확인]은 고른 종목 배열을 돌려준다. 취소·닫기(X)·ESC 는 { isCloseButtonClick } 객체라 배열 여부로 판정한다.
    if (!Array.isArray(result) || result.length === 0) return;

    // AS-IS fn_SetParIsu — 선택 결과로 그리드 전체를 바꾸고 ADD_YN = Y
    dlt_isu.setJSON(result.map(row => ({
        isuCd : row.isuCd ?? "",
        isuNm : row.isuNm ?? "",
        bzProcsNo : "",
        isurCd : row.isurCd ?? "",
        comNm : row.comNm ?? "",
        addYn : "Y",
        status : ""
    })));
    scwin.selectedRow = -1;
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 28
 * @description 저장·수정 전 입력 검증. 종목 1건 이상, 지정일 필수·날짜. (원본 fn_CheckForm — §6.5)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    if (dlt_isu.getRowCount() === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    const options = {
        validateType : "alert",
        checkType : "single",
        fields : {
            edt_DesignDd : { required : true, format : "date", name : "지정일" }
        }
    };
    return await $c.validate.validateDataCollect(panel_3, options);
};

/**
 * @method
 * @name scwin.isSaveSuccess
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록·수정·삭제 응답 판정 — 통신 성공이고 completeYn 이 성공 값이면 true. (§5.3~5.5)
 * @param {Object} result executeDynamic 결과
 * @returns {Boolean} 성공 여부
 * @hidden N
 */
scwin.isSaveSuccess = function (result) {
    // TODO: completeYn 의 성공 값("Y")은 가정 — 명세 확인 필요 (§10 #4)
    return result.responseJSON?.success === true && dma_resultSave.get("completeYn") === scwin.COMPLETE_YN_OK;
};

/**
 * @method
 * @name scwin.getFstDesignDd
 * @author Inswave
 * @date 2026. 10. 28
 * @description 최초지정일 — 이번에 새로 추가한 종목(addYn Y)은 이번 지정일, 부모가 넘긴·이미 지정된 종목은 최초적출일. (원본 fn_save_trs — §6.6)
 * @param {String} addYn 추가여부
 * @returns {String} 최초지정일 (yyyyMMdd)
 * @hidden N
 */
scwin.getFstDesignDd = function (addYn) {
    return (addYn === "Y") ? dma_detail.get("designDd") : scwin.fstDtectDd;
};

/**
 * @method
 * @name scwin.toNoList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 등록 응답의 업무처리번호 목록을 문자열 배열로 만든다 — 배열이면 그대로, 문자열이면 쉼표로 나눈다. (§5.3)
 * @param {Array|String} value 응답 bzProcsNoList
 * @returns {Array} 업무처리번호 배열
 * @hidden N
 */
scwin.toNoList = function (value) {
    if (Array.isArray(value)) return value.map(no => String(no ?? ""));
    if ($c.util.isEmpty(value)) return [];
    return String(value).split(",").map(no => no.trim());
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 28
 * @description 신규 저장. 검증 → 중복 확인 → 확인 → 등록. 성공하면 수정 모드로 바꾸고 종목선택을 잠근다.
 * 응답에 업무처리번호가 모두 오지 않으면 수정·삭제할 키가 없으므로 팝업을 닫는다(부모가 재조회). (원본 fn_save + trs OnSuccess — §6.7, §1.4 업무 3)
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // 원본 순서: 중복 확인이 저장 확인보다 앞
    if (await scwin.checkDuplicate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    const isSuccess = await scwin.registerTrs();
    if (isSuccess === null) return;

    if (!isSuccess) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));

    const rows = dlt_isu.getAllJSON();
    if (rows.some(row => $c.util.isEmpty(row.bzProcsNo))) {
        // TODO: 응답에 번호가 없으면 수정 모드로 갈 수 없다 — 서버 응답 확인 (§10 #4)
        $c.win.closePopup();
        return;
    }

    // 원본: 마지막 행의 번호가 화면 상태값으로 남고, 한 건이면 그 행을 고른다
    scwin.bzProcsNo = rows[rows.length - 1].bzProcsNo;
    if (rows.length === 1) scwin.selectGridRow(0);

    $c.util.setButtonState("grpBtnBox", "update", scwin.BTN_MAP);
    scwin.setIsuBtnState();
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 28
 * @description 수정. 검증 → 확인 → 그리드 행마다 차례로 수정. 한 건이라도 실패하면 실패를 안내한다. (원본 fn_update + trs OnSuccess/OnFail — §6.8, §1.4 업무 4)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    let errCnt = 0;
    for (let i = 0; i < dlt_isu.getRowCount(); i++) {
        const isSuccess = await scwin.modifyTrs(i);
        if (isSuccess === null) return;
        if (!isSuccess) errCnt++;
    }

    await $c.win.alert($c.stf.getMessageParam(errCnt > 0 ? "MSG-A002" : "MSG-A001", "수정"));
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 28
 * @description 삭제. 확인 → 그리드 행마다 차례로 삭제. 모두 성공하면 팝업을 닫고, 실패가 있으면 성공한 행을 지워 실패한 행만 남긴다.
 * 입력 검증은 하지 않는다. (원본 fn_delete + trs OnSuccess/OnFail 의 D 분기 — §6.9, §1.4 업무 5)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    let errCnt = 0;
    for (let i = 0; i < dlt_isu.getRowCount(); i++) {
        const isSuccess = await scwin.removeTrs(i);
        if (isSuccess === null) return;
        if (!isSuccess) errCnt++;
    }

    if (errCnt === 0) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        $c.win.closePopup();
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));

    // 성공한 행을 지운다 — 뒤에서부터 지워야 index 가 밀리지 않는다(규칙 28).
    dlt_isu.setBroadcast(false);
    for (let i = dlt_isu.getRowCount() - 1; i >= 0; i--) {
        if (dlt_isu.getCellData(i, "status") === "Y") dlt_isu.removeRow(i);
    }
    dlt_isu.setBroadcast(true, true);
    scwin.selectedRow = -1;
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr 과 데이터셋 2개다. (§6.10)
 * @param {Number} row 대상 그리드 행 index
 * @returns {Object} 넘길 data
 * @hidden N
 */
scwin.getDsclData = function (row) {
    const isu = dlt_isu.getRowJSON(row);

    return {
        formCd : scwin.DSCL_FORM_CD[scwin.secugrpId] ?? "",                         // AS-IS arr[0] discls_form_cd
        bzProcsNo : isu.bzProcsNo ?? "",                                            // AS-IS arr[1] fr_bz_procs_no
        isurCd : isu.isurCd ?? "",                                                  // AS-IS arr[2] Isur_cd
        mktId : "1",                                                                // AS-IS arr[3] '1'
        isuNm : (scwin.secugrpId === scwin.SECUGRP_ID_EN) ? (isu.isuNm ?? "") : "", // AS-IS arr[5] — ETN 만 종목명
        // AS-IS CopyDataSet(dts_Isu, param_dts_isu) — fn_copy_dts 로 채운 대상 종목 한 건
        isu : [{
            bzProcsNo : isu.bzProcsNo ?? "",
            isuCd : isu.isuCd ?? "",
            isuNm : isu.isuNm ?? "",
            isurCd : isu.isurCd ?? "",
            addYn : isu.addYn ?? ""
        }],
        // AS-IS CopyDataSet(dts_Mst, param_dts_mst) + COM_NM — 입력 폼 + 대상 종목
        mst : [{
            ...dma_detail.getJSON(),
            bzProcsNo : isu.bzProcsNo ?? "",
            isuCd : isu.isuCd ?? "",
            isurCd : isu.isurCd ?? "",
            comNm : isu.comNm ?? ""
        }]
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 28
 * @description 공시안내문작성 팝업을 data 로 넘겨 열고 닫힐 때까지 기다린다. 종목이 여럿이면 그리드에서 고른 행이 대상이다.
 * (원본 fn_dscl — §6.10, 가이드 §6.5)
 * @returns
 * @hidden N
 */
scwin.writeDscl = async function () {
    const rowCount = dlt_isu.getRowCount();

    if (rowCount === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return;
    }
    if (rowCount > 1 && scwin.selectedRow < 0) {
        await $c.win.alert("종목을 선택해 주세요.");
        return;
    }
    if (rowCount === 1) scwin.selectGridRow(0);

    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 825,
        type : "pageFramePopup"
    };

    // TODO: 경로는 가정, 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10 #9)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData(scwin.selectedRow));
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 28
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.10, §10 #9, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [5] 종목명(ETN) 을 채운다
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @returns {Number} arr 길이
 * @hidden N
 */
scwin.getPar = function (arr, dltIsu, dltMst) {
    if (scwin.selectedRow < 0) return arr.length;

    const data = scwin.getDsclData(scwin.selectedRow);

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[5] = data.isuNm;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 28
 * @description 컬럼 정의가 비어 있는 다른 화면의 dataList 에 행을 채운다. setJSON 은 선언된 컬럼만 옮기므로 첫 행의 키로 컬럼을 먼저 만든다.
 * (92024 의 원천 자료 dataList 는 서식마다 컬럼이 달라 부모가 컬럼째 넘긴다 — 원본 CopyDataSet)
 * @param {Object} dataList 채울 dataList (없으면 무시)
 * @param {Array} rows 넣을 행 목록
 * @returns
 * @hidden N
 */
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
